Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word;  // Wort, das gesucht werden soll
    int count = 0;  // Anzahl der Vorkommen

    // Wort von Benutzer einlesen
    cout << "Geben Sie das zu suchende Wort ein: ";
    cin >> word;

    // Dateiname von Benutzer einlesen
    string filename;
    cout << "Geben Sie den Dateinamen ein: ";
    cin >> filename;

    // Datei öffnen
    ifstream file(filename);
    if (!file) {
        cerr << "Fehler: Datei konnte nicht geöffnet werden: " << filename << endl;
        return 1;
    }

    // Zeile für Zeile durch die Datei lesen und Wort zählen
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            pos += word.length();
            count++;
        }
    }

    // Anzeige der Ergebnisse
    cout << "Das Wort '" << word << "' tritt in der Datei '" << filename << "' " << count << " Mal auf." << endl;

    // Datei schließen
    file.close();

    return 0;
}
```

Dieses Programm erfordert, dass Sie den Dateinamen und das zu suchende Wort beim Ausführen des Programms eingeben.

